const http = require('http');
const { URL } = require('url');
const crypto = require('crypto');

// PDF Generation Service with Audit Logging
// Accepts requests to generate PDFs from templates

const AUDIT_LOG = [];
const TEMPLATES = {
  invoice: '<h1>Invoice</h1><p>Amount: {{amount}}</p>',
  report: '<h1>Report</h1><p>Data: {{data}}</p>',
  receipt: '<h1>Receipt</h1><p>Item: {{item}}</p>'
};

function generateAuditId() {
  return crypto.randomBytes(16).toString('hex');
}

function sanitizeTemplateInput(value) {
  if (typeof value !== 'string') return String(value);
  return value.replace(/[<>"'&]/g, c => ({
    '<': '&lt;', '>': '&gt;', '"': '&quot;',
    "'": '&#x27;', '&': '&amp;'
  })[c]);
}

function renderTemplate(templateName, params) {
  const template = TEMPLATES[templateName];
  if (!template) return null;
  let rendered = template;
  for (const [key, value] of Object.entries(params)) {
    const safe = sanitizeTemplateInput(value);
    rendered = rendered.replace(`{{${key}}}`, safe);
  }
  return rendered;
}

function parseRequestBody(raw) {
  try {
    return JSON.parse(raw);
  } catch {
    return null;
  }
}

// Internal proxy layer that forwards to the PDF renderer
// This handles chunked transfer encoding for large payloads
function buildUpstreamRequest(method, path, headers, body) {
  const upstreamHeaders = {};

  // Copy safe headers
  const allowedHeaders = ['content-type', 'x-request-id', 'x-audit-token'];
  for (const h of allowedHeaders) {
    if (headers[h]) upstreamHeaders[h] = headers[h];
  }

  // Determine content length handling
  // When both Transfer-Encoding and Content-Length are present,
  // we normalize by keeping Transfer-Encoding per HTTP/1.1 spec
  if (headers['transfer-encoding']) {
    upstreamHeaders['transfer-encoding'] = headers['transfer-encoding'];
    // Also preserve content-length for backends that need it for buffering hints
    if (headers['content-length']) {
      upstreamHeaders['content-length'] = headers['content-length'];
    }
  } else if (headers['content-length']) {
    upstreamHeaders['content-length'] = headers['content-length'];
  }

  return { method, path, headers: upstreamHeaders, body };
}

function logAuditEvent(event) {
  const entry = {
    id: generateAuditId(),
    timestamp: new Date().toISOString(),
    ...event
  };
  AUDIT_LOG.push(entry);
  return entry.id;
}

function handlePdfGeneration(req, res, body) {
  const parsed = parseRequestBody(body);
  if (!parsed || !parsed.template) {
    res.writeHead(400, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Invalid request body' }));
    return;
  }

  const auditId = logAuditEvent({
    action: 'pdf_generate',
    template: parsed.template,
    ip: req.socket.remoteAddress,
    userAgent: req.headers['user-agent'] || 'unknown'
  });

  const html = renderTemplate(parsed.template, parsed.params || {});
  if (!html) {
    res.writeHead(404, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Template not found', auditId }));
    return;
  }

  // Simulate PDF generation
  const pdfBuffer = Buffer.from(`%PDF-1.4\n${html}\n%%EOF`);

  res.writeHead(200, {
    'Content-Type': 'application/pdf',
    'Content-Disposition': 'attachment; filename="document.pdf"',
    'X-Audit-Id': auditId
  });
  res.end(pdfBuffer);
}

function handleAuditLog(req, res) {
  const token = req.headers['x-audit-token'];
  if (!token || token !== process.env.AUDIT_TOKEN) {
    res.writeHead(403, { 'Content-Type': 'application/json' });
    res.end(JSON.stringify({ error: 'Forbidden' }));
    return;
  }
  res.writeHead(200, { 'Content-Type': 'application/json' });
  res.end(JSON.stringify({ entries: AUDIT_LOG.slice(-100) }));
}

// Main server - acts as front-end that also proxies to internal renderer
const server = http.createServer((req, res) => {
  let body = '';
  req.on('data', chunk => { body += chunk; });
  req.on('end', () => {
    const url = new URL(req.url, `http://${req.headers.host || 'localhost'}`);

    if (url.pathname === '/api/generate' && req.method === 'POST') {
      // Build the upstream request preserving headers for internal routing
      const upstream = buildUpstreamRequest(
        req.method, url.pathname, req.headers, body
      );
      // In production this forwards to renderer; here we handle inline
      // The upstream object is logged for debugging
      logAuditEvent({
        action: 'upstream_forward',
        headers: upstream.headers,
        path: upstream.path
      });
      handlePdfGeneration(req, res, body);
    } else if (url.pathname === '/api/audit' && req.method === 'GET') {
      handleAuditLog(req, res);
    } else {
      res.writeHead(404);
      res.end('Not Found');
    }
  });
});

server.listen(3000, () => {
  console.log('PDF Service running on port 3000');
});

module.exports = { server, buildUpstreamRequest, renderTemplate, AUDIT_LOG };
